namespace {using U=std::uint32_t;
template<class F>bool fails(F f){try{f();}catch(const std::exception&){return true;}return false;}
std::string text(const dfre::MissionClientAddedBindings&b,U at){std::string s;for(U i=0;i<4096;++i){const auto c=b.read(at+i,1);if(!c)return s;s+=char(c);}throw std::runtime_error("Native startup text exceeds its fixture extent");}
void write_text(const dfre::MissionClientAddedBindings&b,U at,const std::string&s){for(U i=0;i<=s.size();++i)b.write(at+i,1,i<s.size()?std::uint8_t(s[i]):0);}
// Required493A80 fixture for the two verified caller literals. This is not a CRT port.
U format(const dfre::MissionClientAddedBindings&b,const std::vector<U>&a){assert(a.size()==3);const auto literal=a[1]==0x4ccc60?"STR_PWNAME%02i":a[1]==0x4ccc80?"STR_SPWNAME%02i":"";assert(*literal&&text(b,a[1])==literal);const U value=a[2];assert(value<39);auto digits=std::to_string(value);if(digits.size()<2)digits="0"+digits;const auto s=std::string(a[1]==0x4ccc60?"STR_PWNAME":"STR_SPWNAME")+digits;write_text(b,a[0],s);return U(s.size());}
struct Memory{std::map<U,dfre::AssetBytes>blocks;std::uint8_t*ptr(U a,U n){auto i=blocks.upper_bound(a);if(i==blocks.begin())throw std::runtime_error("Native weapon startup memory is not mapped");--i;if(std::uint64_t(a-i->first)+n>i->second.size())throw std::runtime_error("Native weapon startup span exceeds its owner");return i->second.data()+a-i->first;}U read(U a,U n){U v=0;for(U i=0;i<n;++i)v|=U(*ptr(a+i,1))<<(8*i);return v;}void write(U a,U n,U v){for(U i=0;i<n;++i)*ptr(a+i,1)=std::uint8_t(v>>(8*i));}};
void declared(){using namespace dfre;Memory m;m.blocks[0x400000].resize(0xa00000);m.blocks[0x1200000].resize(0x4000);MissionClientAddedBindings b;b.read=[&](U a,U n){return m.read(a,n);};b.write=[&](U a,U n,U v){m.write(a,n,v);};const auto put=[&](U a,U v,U n=4){b.write(a,n,v);};const U table=0x1200000,frame=0x1201000;write_text(b,0x4ccc60,"STR_PWNAME%02i");write_text(b,0x4ccc80,"STR_SPWNAME%02i");write_text(b,0x4ccc70,"Player Weapons");put(table,0x54585452);put(table+4,0x100);put(table+12,2);put(table+16,0);put(table+32,8);write_text(b,table+48,"Primary");write_text(b,table+56,"Secondary");put(table+0x100,1);put(table+0x104,0x7c);put(table+0x108,2);write_text(b,table+0x10c,"Player Weapons");write_text(b,table+0x180,"STR_PWNAME00");write_text(b,table+0x18d,"STR_SPWNAME00");MissionSoundAssetBindings raw;raw.read=b.read;raw.write=b.write;mission_rtxt_fixup(raw,table);put(0x503230,table);put(0x4f9934+0x64,4005);put(0x4f9934+0x68,4004);put(0x4f9934+0x74,5);put(0x4f9934+0x9c,17);std::vector<RuntimeItemDefinition>defs(3);defs[1].id=4005;defs[2].id=4004;U names=0,resolvers=0;bool missing_graphics=false;MissionLocalizationBindings loc;loc.read=b.read;loc.lookup_49a092=[&](U t,U g,U k){return mission_rtxt_lookup(raw,t,g,k);};b.call=[&](U site,const auto&a)->U{if(site==0x493a80)return format(b,a);if(site==0x404cf0){if(++names==1)put(0xad3edc,1);return mission_localized_text(loc,a[0],a[1]);}if(site==0x4828c0){if(missing_graphics)throw std::runtime_error("Required graphic lookup is absent");++resolvers;return U(runtime_item_index(defs,a[0]));}throw std::runtime_error("Native weapon startup service is not bound");};mission_weapon_startup(b,frame,32);assert(names==2&&resolvers==2&&text(b,0x4f9938)=="Primary"&&text(b,0x4f9978)=="Secondary");assert(b.read(0x4f9934+0x94,4)==1&&b.read(0x4f9934+0x98,4)==2);assert(b.read(0xad3ee4,4)==0x4f9154&&b.read(0xad3ee0,4)==28&&b.read(0xad3ed4,4)==0x4f9704&&b.read(0xad3ed8,4)==28&&b.read(0xad3ed0,4)==0x4f9934&&b.read(0xad3edc,4)==1);for(U i=0;i<63;++i)assert(b.read(0xad3dd0+i*4,4)==(i==4?17u:600u));auto absent=b;absent.call={};put(0xad3ed0,0);assert(fails([&]{mission_weapon_startup(absent,frame,32);}));assert(b.read(0xad3ed0,4)==0x4f9934&&b.read(0xad3edc,4)==39);assert(fails([&]{mission_weapon_startup(b,frame,31);}));missing_graphics=true;put(0x4f9934+0x94,0xabcdef01);names=0;assert(fails([&]{mission_weapon_startup(b,frame,32);}));assert(names==2&&b.read(0x4f9934+0x94,4)==0xabcdef01&&text(b,0x4f9938)=="Primary");std::cout<<"declared weapon startup/current RTXT/resolver-prefix checks passed\n";}
void actual(const std::filesystem::path&game){using namespace dfre;AssetStore assets(game);std::ifstream input(game/"Df.exe",std::ios::binary);AssetBytes executable((std::istreambuf_iterator<char>(input)),{});if(executable.empty())throw std::runtime_error("Original Df.exe is missing");auto defs=build_runtime_items(load_item_catalog(assets));Fixed3 listener{};U yaw=0;MissionAudioFrameCells audio{0,listener,yaw};const TerrainGeometry*terrain=nullptr;MissionSoundRuntime sound(assets,executable,audio,terrain,{});const auto&raw=sound.asset_bindings();MissionClientAddedBindings b;b.read=raw.read;b.write=raw.write;const auto alloc=[&](U size){return raw.call(0x497f60,{size,4,0,0});};const U filename=alloc(64),frame=alloc(32);write_text(b,filename,"DFGAME.BIN");const auto table=mission_rtxt_load(raw,filename);if(!table)throw std::runtime_error("Supplied localization failed to load");raw.write(0x503230,4,table);raw.write(0x67dbc9,1,0);MissionLocalizationBindings loc;loc.read=b.read;loc.lookup_49a092=[&](U t,U g,U k){return mission_rtxt_lookup(raw,t,g,k);};U names=0,resolvers=0;std::vector<std::string>localized;std::vector<U>resolved;b.call=[&](U site,const auto&a)->U{if(site==0x493a80)return format(b,a);if(site==0x404cf0){++names;const auto result=mission_localized_text(loc,a[0],a[1]);localized.push_back(text(b,result));return result;}if(site==0x4828c0){++resolvers;const U result=U(runtime_item_index(defs,a[0]));resolved.push_back(result);return result;}throw std::runtime_error("Actual weapon startup boundary is not bound");};mission_weapon_startup(b,frame,32);assert(names==78&&resolvers==78&&b.read(0xad3edc,4)==39);U nonempty=0,nonzero_graphics=0;for(U i=0;i<39;++i){const U row=0x4f9934+i*0xa8;assert(text(b,row+4)==localized.at(i*2)&&text(b,row+0x44)==localized.at(i*2+1));assert(b.read(row+0x94,4)==resolved.at(i*2)&&b.read(row+0x98,4)==resolved.at(i*2+1));nonempty+=!localized.at(i*2).empty();nonzero_graphics+=resolved.at(i*2)!=0;assert(b.read(row+0x94,4)<defs.size()&&b.read(row+0x98,4)<defs.size());}assert(nonempty>0&&nonzero_graphics>0);for(U i=0;i<28;++i)assert(std::int32_t(b.read(0xad3dd0+i*4,4))<=600);raw.call(0x4980d0,{frame});raw.call(0x4980d0,{filename});std::cout<<"actual PE39rows78localizations78graphics currentRTXT names="<<nonempty<<" resolved="<<nonzero_graphics<<" device_output0 network_output0\n";}
}
int main(int argc,char**argv){try{declared();if(argc==2)actual(argv[1]);else if(argc!=1)throw std::runtime_error("Use: native_mission_weapon_startup [GAME_FOLDER]");return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
